# modeller.py
class Ogrenci:
    def __init__(self, ad, no, vize, final):
        self.ad = ad
        self.no = no
        self.vize = vize
        self.final = final

    def ortalama(self):
        return (self.vize * 0.4) + (self.final * 0.6)

# urunler.py
class Urun:
    def __init__(self, ad, fiyat):
        self.ad = ad
        self.fiyat = fiyat

# kasa.py
def fis_hesapla(urun_listesi):
    return sum(u.fiyat for u in urun_listesi)
